/** 
 * Open a chat room window. In IRC a situation may occur where the user gets joined to a channel without Jitsi initiating the joining activity. This "unannounced" join event, must also be handled and we should display the chat room window in that case, to alert the user that this happened.
 * @param chatRoom the chat room
 */
private void openChatRoomWindow(ChatRoomIrcImpl chatRoom){
  MUCService mucService=IrcActivator.getMUCService();
  ChatRoomWrapper wrapper=mucService.getChatRoomWrapperByChatRoom(chatRoom,true);
  mucService.openChatRoom(wrapper);
}
